sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    var instanceUrl = gs.getProperty('glide.servlet.uri');

    // Pulls the sys_id of the target record, not the approval record
    var link = instanceUrl +
    "x/enno/gatenow-workspace/record/x_enno_gatenow_grant_program/" +
    current.document_id;

    template.print(link);

})(current, template, email, email_action, event);
